      "content": "{\n  \"name\": \"dsh-feishu\",\n  \"version\": \"0.1.0\",\n  \"description\": \"Deep Feishu / Lark integration for DeepSeek Harness: create Bitable apps, docs, sheets, wiki nodes, uploads and messages in the user's own cloud workspace, plus a user OAuth flow.\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": {\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"default\": \"./lib/ui/client.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"skill\",\n    \"scripts\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"LICENSE\",\n    \"cordis.patch.yml\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-slots\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"test\": \"node test/run-tests.mjs\",\n    \"install:profile\": \"pwsh -File scripts/install.ps1\",\n    \"uninstall:profile\": \"pwsh -File scripts/uninstall.ps1\"\n  },\n  \"engines\": {\n    \"node\": \">=20\"\n  },\n  \"license\": \"MIT\",\n  \"author\": \"Run Liu\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/2048lr/dsh-feishu.git\"\n  },\n  \"homepage\": \"https://github.com/2048lr/dsh-feishu#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/2048lr/dsh-feishu/issues\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"feishu\",\n    \"lark\",\n    \"bitable\",\n    \"多维表格\",\n    \"飞书\",\n    \"deepseek-harness\"\n  ]\n}\n"
